{
  "selections": [
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data"],
      "relevance": "상담사가 '황당함은 어떤 거였어요?'라고 묻는 지점에서, 내담자가 '1등을 만들어놓고 폭언 가해자 취급을 받는' 상황을 황당하게 느끼는 핵심은 '나는 특별한 사람이므로 보통 사람들에게 적용되는 규칙과 대우가 나에게 그대로 적용되어서는 안 된다'는 신념이 깨졌기 때문. 성장 배경에서 어머니가 '너는 다른 애들과는 급이 다르다'고 반복한 경험이 이 신념의 원천."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_positive",
      "background_ids": ["/situations/0"],
      "relevance": "내담자가 '제 말 한마디면 움직이는 게 정상'이라고 말하고, 신고가 들어온 순간 '실적으로 답할 거라는 믿음'이 흔들렸다고 서술하는 지점에서, '압도적 성과를 내면 사람들이 내 방식에 토를 달지 못할 것'이라는 가정이 현실과 충돌한 상황이 드러남. 상황 사례 0의 자동사고 '3년 연속 1등 만들어 준 사람한테 지금 뭐 하자는 거야'와 동일한 구조."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_negative",
      "background_ids": [],
      "relevance": "내담자가 '회사가 실적을 보는 눈이 없다는 걸 확인한 거죠'라며 외부 탓으로 전환하는 순간, 만약 보통 사람들과 같은 취급을 받는다면 자신이 '특별할 것 없는 그저 그런 사람'이 된다는 두려움이 작동하고 있을 가능성이 있음. 상담사의 황당함 질문이 이 두려움에 닿을 수 있는 지점."
    },
    {
      "trait_id": "/coping_strategies/0",
      "background_ids": ["/situations/0"],
      "relevance": "대화 전반에서 내담자가 인사팀을 '실적 한 번도 못 만들어 본 사람들'로 규정하고, 상담을 '오라고 해서 온' 자리로 격하하는 패턴이 이 대처 전략과 일치. 황당함의 질을 탐색하는 상담사의 질문에 대해 내담자가 다시 상대의 자격을 문제 삼아 회피할 가능성이 높음."
    }
  ]
}

